import{_ as e,c as o,o as s,a2 as i}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Preguntas frecuentes","description":"Respuestas sobre el precio, la privacidad, los Mac compatibles, las carpetas, los idiomas y la restauración de una compra.","frontmatter":{"title":"Preguntas frecuentes","description":"Respuestas sobre el precio, la privacidad, los Mac compatibles, las carpetas, los idiomas y la restauración de una compra."},"headers":[],"relativePath":"es/guide/faq.md","filePath":"es/guide/faq.md","lastUpdated":1794296122000}'),r={name:"es/guide/faq.md"};function n(t,a,c,l,u,p){return s(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><h3 id="¿qdiff-es-gratuito" tabindex="-1">¿qDiff es gratuito? <a class="header-anchor" href="#¿qdiff-es-gratuito" aria-label="Permalink to &quot;¿qDiff es gratuito?&quot;">​</a></h3><p>Sí. Todas las comparaciones, vistas y exportaciones funcionan sin pagar. La versión gratuita solo muestra una pequeña marca de «Sin licencia» en la barra de pestañas. Una compra única la elimina e incluye futuros extras premium. No hay suscripción ni publicidad.</p><h3 id="¿la-compra-desbloquea-alguna-funcion" tabindex="-1">¿La compra desbloquea alguna función? <a class="header-anchor" href="#¿la-compra-desbloquea-alguna-funcion" aria-label="Permalink to &quot;¿La compra desbloquea alguna función?&quot;">​</a></h3><p>No: todas las funciones ya están disponibles. La compra elimina la marca. Si más adelante añadimos extras premium, pasarán a formar parte de esa misma compra única en lugar de un producto nuevo.</p><h3 id="¿como-restauro-mi-compra" tabindex="-1">¿Cómo restauro mi compra? <a class="header-anchor" href="#¿como-restauro-mi-compra" aria-label="Permalink to &quot;¿Cómo restauro mi compra?&quot;">​</a></h3><p>Abra <strong>Ajustes → Premium</strong> y elija <strong>Restaurar compras</strong>. Las compras están vinculadas a su Apple ID, por lo que también funcionan en sus otros Mac.</p><h3 id="¿que-mac-son-compatibles" tabindex="-1">¿Qué Mac son compatibles? <a class="header-anchor" href="#¿que-mac-son-compatibles" aria-label="Permalink to &quot;¿Qué Mac son compatibles?&quot;">​</a></h3><p>macOS 12 o posterior, en Mac con chip de Apple y con Intel. Consulte los <a href="./download.html#system-requirements">requisitos del sistema</a>.</p><h3 id="¿necesito-una-cuenta-o-conexion-a-internet" tabindex="-1">¿Necesito una cuenta o conexión a internet? <a class="header-anchor" href="#¿necesito-una-cuenta-o-conexion-a-internet" aria-label="Permalink to &quot;¿Necesito una cuenta o conexión a internet?&quot;">​</a></h3><p>No. qDiff funciona sin conexión, no requiere iniciar sesión y no tiene ningún servicio en segundo plano. Solo abre los archivos y carpetas que usted elige.</p><h3 id="¿puede-comparar-carpetas-completas-y-archivos-comprimidos" tabindex="-1">¿Puede comparar carpetas completas y archivos comprimidos? <a class="header-anchor" href="#¿puede-comparar-carpetas-completas-y-archivos-comprimidos" aria-label="Permalink to &quot;¿Puede comparar carpetas completas y archivos comprimidos?&quot;">​</a></h3><p>Sí. Las carpetas se abren como un árbol con filtros por estado y acciones de copia y sincronización. Un archivo .zip o .tar se puede comparar como una carpeta sin descomprimir.</p><h3 id="¿que-pasa-con-las-imagenes-y-los-archivos-que-no-son-de-texto" tabindex="-1">¿Qué pasa con las imágenes y los archivos que no son de texto? <a class="header-anchor" href="#¿que-pasa-con-las-imagenes-y-los-archivos-que-no-son-de-texto" aria-label="Permalink to &quot;¿Qué pasa con las imágenes y los archivos que no son de texto?&quot;">​</a></h3><p>Las imágenes se pueden ver una al lado de otra o superpuestas. Los archivos que no son de texto plano se pueden comparar hasta el más mínimo detalle. Consulte <a href="./more.html">más formas de comparar</a>.</p><h3 id="¿va-a-subir-o-analizar-mis-archivos" tabindex="-1">¿Va a subir o analizar mis archivos? <a class="header-anchor" href="#¿va-a-subir-o-analizar-mis-archivos" aria-label="Permalink to &quot;¿Va a subir o analizar mis archivos?&quot;">​</a></h3><p>No. No se recopila, rastrea ni sincroniza nada. La explicación completa está en la <a href="./../privacy/">Política de Privacidad</a>.</p><h3 id="¿la-interfaz-esta-disponible-en-espanol-y-otros-idiomas" tabindex="-1">¿La interfaz está disponible en español y otros idiomas? <a class="header-anchor" href="#¿la-interfaz-esta-disponible-en-espanol-y-otros-idiomas" aria-label="Permalink to &quot;¿La interfaz está disponible en español y otros idiomas?&quot;">​</a></h3><p>Sí. La interfaz está disponible en siete idiomas: inglés, chino simplificado, chino tradicional, japonés, alemán, español y francés, con apariencia clara y oscura.</p><h3 id="algo-no-funciona-¿que-puedo-hacer" tabindex="-1">Algo no funciona. ¿Qué puedo hacer? <a class="header-anchor" href="#algo-no-funciona-¿que-puedo-hacer" aria-label="Permalink to &quot;Algo no funciona. ¿Qué puedo hacer?&quot;">​</a></h3><p><a href="./support.html">Escríbanos</a> indicándonos su versión de macOS y una breve descripción de lo ocurrido. Una captura de pantalla ayuda mucho.</p>',21)])])}const h=e(r,[["render",n]]);export{m as __pageData,h as default};
